const FOOTER = `╭─────୨୧────╮ ✦ ${toFont('Bᴇʀᴜ V10 • Sᴍᴏᴏᴛʜ • Fᴀsᴛ • Cʟᴇᴀɴ')} ╰─────୨୧────╯`;
// ==================== LOADING BARS ====================
const LOADING_BARS = ["▰▱▱▱▱", "▰▰▱▱▱", "▰▰▰▱▱", "▰▰▰▰▱", "▰▰▰▰▰"];
async function sendLoadingMessage(sock, jid, emoji, title, message) {
const loadingText = `╭────୨୧─────╮
${emoji}  ${toFont(title || 'Loading...')}
╰─────୨୧─────╯
${toFont(message || 'Please wait...')}
${LOADING_BARS[0]}
${FOOTER}`;
const msg = await sock.sendMessage(jid, { text: loadingText });
return msg;
}
async function updateLoadingBar(sock, jid, msgKey, step) {
const barIndex = Math.min(step, LOADING_BARS.length - 1);
const updatedText = `╭────୨୧─────╮
⏳  ${toFont('Processing...')}
╰─────୨୧─────╯
${toFont('Executing command')}
${LOADING_BARS[barIndex]}
${FOOTER}`;
await sock.sendMessage(jid, { text: updatedText, edit: msgKey });
}
async function animateLoading(sock, jid, msgKey, duration = 2000) {
const steps = 5;
const delayMs = duration / steps;
for (let i = 0; i < steps; i++) {
await delay(delayMs);
await updateLoadingBar(sock, jid, msgKey, i);
}
await updateLoadingBar(sock, jid, msgKey, 4);
await delay(300);
}
// ==================== STYLISH REPLY ====================
function formatStylishReply(emoji, title, message, footer = null) {
return `╭────୨୧─────╮
${emoji}  ${toFont(title)}
╰─────୨୧─────╯
${toFont(message)}
${footer ? toFont(footer) : ''}
${FOOTER}`;
}
async function sendStyledReply(sock, jid, emoji, title, message, footer = null, mentions = []) {
const styled = formatStylishReply(emoji, title, message, footer);
await sock.sendMessage(jid, { text: styled, mentions: mentions });
}
